import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DpI_zlPE.js";var i=JSON.parse(`{"title":"diy桌游","description":"","frontmatter":{},"headers":[],"relativePath":"ccc/自扫自印/diy桌游.md","filePath":"ccc/自扫自印/diy桌游.md"}`),a={name:`ccc/自扫自印/diy桌游.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="diy桌游" tabindex="-1">diy桌游 <a class="header-anchor" href="#diy桌游" aria-label="Permalink to “diy桌游”">​</a></h1><h2 id="制图" tabindex="-1">制图 <a class="header-anchor" href="#制图" aria-label="Permalink to “制图”">​</a></h2><p><a href="https://sgs.miscity.cn:20081" target="_blank" rel="noreferrer">diy三国杀网页制图工具</a>；<a href="https://pandagm.com/tools/" target="_blank" rel="noreferrer">Panda提供的设计指南，范例，工具</a>；<a href="https://space.bilibili.com/9661652" target="_blank" rel="noreferrer">zyydi制图教程</a>；</p><p><a href="https://pan.baidu.com/s/1157YMU_3r-lmIhKt1RKNjQ?pwd=bxzz" target="_blank" rel="noreferrer">百度网盘</a></p><blockquote><p>附indesign模板，可用于HP indigo彩印，配有批处理辅助脚本和演示视频。</p><p>附PS动作：自动生成出血，圆角卡图补齐直角，PS可以自动批处理。另有topazAI软件，可用于超分辨率卡图，支持cpu。</p><p>AI扩图，对文本框，边框的处理暂时不理想，只适合扩图原画出血。尝试用<a href="https://space.bilibili.com/12566101" target="_blank" rel="noreferrer">秋葉aaaki</a>的comfyui整合包，网盘转载两个工作流。用comfyui整合包的节点管理器修复缺失的节点。</p></blockquote><p>200多块买台重型冲卡器即可自印，网友用拼740x510mm大版模板，同城HP indigo数码印刷机300g铜版纸双面彩印覆膜，8￥，可冲55张卡，折合单价1毛5。</p><p>自己冲卡，牌面出血可以每边只留0.5mm，冲卡时用白边大小作为参照确保不歪斜然后平移消弭白边，再冲卡。出血留的小，最歪也不过1~2°左右，基本感知不到，再歪就会露白。</p><p>外面做卡，出血基本要每边1~2mm。</p><p><strong>INDIGO最好覆膜，不然指甲一抠就能抠下来。</strong></p><p>据网友风信子反馈小字存在明显的笔画断裂现象，不过<strong>文字辨识度不成问题</strong>。凑近了细看能察觉有印刷网纹，原画看起来不够细腻。后文INDIGO章节附图。</p><p><strong>网友反馈，霜X有类似的一模一样的笔画断裂现象</strong>，对比之下推测可能是indigo12000或更老的机型。</p><p>据网友风信子反馈hp 12000及更早机型上比较容易感知印刷网纹，而相对比较新的的hp 15k要细腻一些，相对更不易感知网纹，笔画断裂现象也有改善，更新的是<strong>HD</strong>机型。</p><p>我推测<strong>可能是图文快印商家的质量设置为速度优先</strong>。图文快印的indigo自印足以胜任DIY来玩。后文indigo彩印有进一步介绍。</p><p>自己冲卡，<strong>我喷墨单打印</strong>鱼“不晓自在”，6色染料/10色颜料。<a href="./dy.buxiaozizai.com.html">详细了解</a></p><p>画册、影集不推荐市面上一切胶装，热熔胶寿命就几年，都不用翻来翻去，自己放着就会老化脱胶。省力的话，插页资料册，插页资料册有个隐形优点，兼容颜料主要短板就是反光观感怪异，但是隔着塑料膜就不存在这个问题了。</p><p>DIY画册影集，买一本影集如“中国摄影”或网上视频，参考蝴蝶装的样子。用书边带+无酸白胶粘书脊，用一个大夹子夹住，有书边带要牢靠非常多，即使运气不好脱胶了，自己修补也非常方便。或干脆全部摊开来放在无酸档案盒。</p><p><strong>桌游代工厂</strong>有商家54张x10份这样的数量就能做，单价可能在5毛/卡左右。</p><h3 id="硬挺度" tabindex="-1">硬挺度 <a class="header-anchor" href="#硬挺度" aria-label="Permalink to “硬挺度”">​</a></h3><p>官正诸如珍藏版典藏版之所以更硬挺，是因为涂布了上光浆料，会放硬挺剂，所以350g相对DIY的300g纸张硬挺很多，DIY想要实现较高的硬挺度，可行的方法是覆加厚的PET膜，不过据z佬说观感会更暗。</p><h2 id="切卡" tabindex="-1">切卡 <a class="header-anchor" href="#切卡" aria-label="Permalink to “切卡”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>三国杀：62x87mm-R3mm</span></span>
<span class="line"><span>St（万智牌；一般桌游都用这个尺寸）：63x88mm-R3mm</span></span>
<span class="line"><span>有一些网站标注万智是63.5x88.9mm，但据老外分享，DIY做63x88mm正好。</span></span>
<span class="line"><span>标准扑克尺寸： 63.5x88.9mm，（2.5寸x3.5寸）</span></span></code></pre></div><ul><li><p>铡刀型切纸刀+省力型倒角钳，成本低，就是费事，几乎不能控制尺寸一致性。</p></li><li><p>定制重型冲卡机， <a href="https://shop104152472.taobao.com/" target="_blank" rel="noreferrer">淘宝·印后 相册 广告设备专销店</a>，是我找到报价最低的，200+12邮费，可能还有更便宜的。</p></li></ul><p>出血留大了目视对齐容易歪斜，想要避免歪斜，目视对齐的一面出血要小，靠白边的大小来判断是否歪斜，然后平移消弭白边。要注意力集中，也是比较费事的，稍微一松懈可能良率就会下降。</p><ul><li>定制电动名片切卡机+手动圆角机成本700+200，机器不算很大。相对省力，不需要集中注意力。</li></ul><p>小型机器只能切不覆膜的350g纸。切出来是直角，需要手动圆角机切圆角，由于R3圆角太小，稍微有点误差视觉上会比较明显，主要表现是倒角不对称。</p><blockquote><p>切卡机优选indigo不覆膜，刚需牌套。</p><p>小型机只能切不覆膜的纸张，喷墨自印最好用颜料墨水，便宜染料耐候性受限，好的染料又要贵很多。</p><p>水性颜料墨水优选爱普生P708，机器较贵。爱普生L8058、L8168机型可行的方案是“铜版纸速干颜料墨水”，堵头风险可能更大，往往也未必稳定性。后文进一步展开。</p></blockquote><ul><li>电动压痕机700~800左右，把划线刀换成切割刀，客服说可以切割覆膜350g纸。</li></ul><p>客服说能切的机器基本有460mm宽，占地面积很大，而且要横切一刀再竖切一刀，就一台机器要重调刀具位置，想省力一点的话可能要弄两台机器。</p><ul><li><p>能切覆膜纸的电动切卡机，一次进纸完成切卡，定制7.8K，阿里巴巴“广州缔森机电设备有限公司”。</p></li><li><p>2~3万左右定制的自动冲卡机，人工上料，需要人工对准1个激光参考锚点，冲卡是倒好角的，机器占地面积很大。闲鱼用户“光信制卡厂”。</p></li><li><p>印刷厂用模切机</p></li></ul><p>核心原理是刀模，然后机器施加压力，有直上直下的，有滚筒施加压力的。进纸有人工上料对准的，有人工上料后自动对准的，有自动上料的。</p><p>搜索关键词：扑克自动冲卡机，早教卡自动冲卡机。</p><p>扑克牌印刷厂看视频有些先切成出血大小，然后叠一起用同一个模具模切，不知道是不是为了一致性。</p><p>搜索关键词：商标液压模切机</p><h2 id="indigo彩印" tabindex="-1">INDIGO彩印 <a class="header-anchor" href="#indigo彩印" aria-label="Permalink to “INDIGO彩印”">​</a></h2><p>参考前文自行切卡，既印刷又切卡往往收费不菲，误差还大，只印刷便宜很多。</p><p>网友用拼740x510mm大版模板，找同城HP indigo数码印刷机300g铜版纸双面彩印覆膜，8块，可冲55张卡，折合单价1毛5。</p><p><strong>INDIGO最好覆膜，不然指甲一扣就能扣下来。</strong></p><p>商家的覆膜机大多是液压的，比diy的小型机覆膜牢靠。indigo机器自带密度仪，<strong>能保证下限</strong>。线上加上邮费成本还是偏高。</p><p>线下试试抖音上搜，或搜招indigo操作员的公司。</p><p>从群友风信子返图来看，<strong>小字存在明显的笔画断裂现象</strong>，不过<strong>文字辨识度不成问题</strong>。凑近了细看能察觉有印刷网纹，原画看起来不够细腻。</p><p>indigo原理是液体电子油墨在橡皮布加热转印成膜，这个过程免不了墨点可能流动，看起来会有点肉是正常现象。</p><p>图文快印INDIGO小字笔画断裂：</p><p><img src="https://s2.loli.net/2025/10/18/fm7xKQaqJTMkpCZ.jpg" alt=".jpg"></p><p>左INDIGO右喷墨，这家INDIGO相对烂一点：</p><p><img src="https://s2.loli.net/2025/10/18/8yzmvLM9wcdYenR.jpg" alt="-.jpg"></p><p>左INDIGO右喷墨，这家INDIGO相对好一点：</p><p><img src="https://s2.loli.net/2025/10/18/cdEFzBXH41UgbD5.jpg" alt="-.jpg"></p><p><strong>网友反馈，霜X有类似的一模一样的笔画断裂现象</strong>，对比之下推测可能是indigo12000或更老的机型。</p><p>据网友风信子反馈hp 12000及更早机型上比较容易感知印刷网纹，而相对比较新的的hp 15k要细腻一些，相对更不易感知网纹，笔画断裂现象也有改善，更新的是<strong>HD</strong>机型。</p><p><strong>我推测可能是图文快印商家的质量设置为速度优先。</strong></p><p>市场很现实，报价低的图文快印商家基本都在内卷打价格战，往往是多年机龄的老机器，第三方维保，机器能跑起来就行，对效果都是非常凑合。</p><p>如果要更好的效果可能要找那些用indigo做影集，画册的商家，并确认其打印质量设置开的是最高档，但价格就不是贵一点点了，或干脆压根不接小单。indigo质量开高点效果应该还可以，如正印坊的定制自称就是indigo4色。</p><p>通常工业生产的规律就决定了需要足够单量来摊薄成本，而DIY自印卡太小众，只能蹭。如果对广告图文快印商家的品质不满意，考虑蹭包装印刷的商家，其中不乏有G7认证，至少有色彩管理操作经验，实际不一定严格色彩管理，但要求做ICC是可以做的。<strong>不过往往报价会贵很多。</strong></p><p>淘宝·皓玥书印装帧定制，indigo12000六色（CMYK+LC+LM）有白墨，可能可以印PVC之类的，能做ICC。报价较贵。</p><p><strong>商家都不老实，相当一部分是嘴巴选手，老旧机器+兼容油墨，但是往往牛逼吹得震天响，报价又高，真的是很恶心。</strong></p><blockquote><p>被我逮捕的一个嘴巴选手：晨曦印刷厂（宿迁盛晨趣商贸有限公司）。</p></blockquote><p><strong>澜达印刷机</strong>是HP indigo的发明人最新力作，同样通过橡皮布转印，但indigo是类似于激光打印机的静电吸附颗粒成像，而Landa则是喷墨成膜转印。相对喷墨兼容颜料应该明显改善界面反射率差异引起的颜料烫金效应，据Landa介绍，其墨水D50粒径约50nm，性能相当不俗，颜料颗粒的粒径过大可能会影响雾度，导致其看起来发灰。应该说Landa品质上应该接近喷墨水平，尤其是选配所谓PrintAI模块号称达到1200x1200dpi，完全是爱普生级别的喷墨水平。但是由于种种原因，澜达公司目前正在破产重组，此前上海丽邱源、河南盛大买了机器，但是好像没有拉过来安装。</p><p><strong>除了indigo彩印，其他数码印刷方式介绍：</strong></p><p>会做色彩管理的，往往定位较高，比如艺术微喷，要价不菲。</p><p>价格实惠的基本只有图文广告市场的商家，一般都不做色彩管理，需要设备保证下限。</p><p>激光碳粉机，大面积堆色会掉粉，还不好做色彩管理，碳粉随着使用会变。输出往往含硅油，覆膜不是最牢靠。</p><p>小图文店喷墨打印机如果用白卡纸，表现力受限。如果用喷墨铜版纸有报价实惠的，可以考虑参考<a href="https://zhuanlan.zhihu.com/p/2024923980432250737" target="_blank" rel="noreferrer">相机翻拍校色打印机</a>。</p><p><strong>喷墨打印机不是一次进纸双面打印，往往正反面位置有偏差，自己的机器还能调模板，外面打印就比较麻烦了。</strong></p><p>喷墨+铜版纸专用颜料墨水的<strong>数码印刷机</strong>（和打印机区分）已经面世。这种大机器一般都有下限。</p><blockquote><p>喷墨高光铜版纸涂布有喷墨涂层吸墨。印刷铜版纸准确来说叫印刷涂布纸，搭配的铜版纸专用颜料墨水不需要喷墨涂层就可以打印。</p></blockquote><h2 id="diy打印双面对齐" tabindex="-1">DIY打印双面对齐 <a class="header-anchor" href="#diy打印双面对齐" aria-label="Permalink to “DIY打印双面对齐”">​</a></h2><p>Indesign排好版，链接图片，让内容缩放适配框架。喷墨打印机上限纸器装纸以后推紧。打印测试用尺量偏移再微调模板文件，我一般牌面文件固定，微调牌背的文件。</p><p>通常纸张纵向和横向的硬挺度不一样，一般纵向上会相对更硬挺一点，所以一般A4最好3x3排列。</p><h2 id="覆膜·塑封" tabindex="-1">覆膜·塑封 <a class="header-anchor" href="#覆膜·塑封" aria-label="Permalink to “覆膜·塑封”">​</a></h2><ul><li>冷裱膜是pvc，特别厚，而且很软，手感像套了个手机软壳。</li><li>覆膜（热裱膜）普通bopp预涂膜不防刮，指甲可以划出白痕，有些膜不顺滑。 <ul><li>光膜是镜面反射，会成像，和原卡差异较大。</li><li>哑膜几乎没有反光，同原卡有差异。</li><li>防刮BOPP哑膜手感有一点粘腻，新的银行卡上面贴的保护膜那种感觉，没有质感。</li><li>阿里巴巴天宝印刷，一款21柔光膜，一款微米30哑膜。光泽度介于哑膜亮膜之间，柔光膜会成像偏漫反射，观感和过光油原卡相对接近些。哑膜则是有一定光泽度的漫反射，相对比较接近覆膜原卡。</li><li><strong>DIY优选PET哑膜，可以改善走纸印和棘轮印。</strong>不怕刮，相对更硬挺。</li><li>淘宝 艺都千帆塑封工厂，联系客服买PET哑膜。有加厚的，更硬挺。不过据z佬说观感会更暗。</li></ul></li><li><strong>印刷厂液压覆膜压力大，还会过压纹机，切割后还是很服帖，diy覆膜可能翘边，起膜。</strong></li><li>印刷厂过压纹机可以做凹凸手感和纹路；diy定制十字布纹预涂膜，只有纹理没有凹凸手感。</li></ul><p>小型台式覆膜机，新机器看看淘宝同一数码科技的机器便宜点。没有液压机劲大，<strong>尽量买可以调速的，可以把速度调慢点来改善效果。</strong></p><h3 id="塑封膜" tabindex="-1">塑封膜 <a class="header-anchor" href="#塑封膜" aria-label="Permalink to “塑封膜”">​</a></h3><ul><li><p>无论是覆膜还是塑封，都是热熔胶合膜层和打印面，开胶撕掉会把打印的图案撕走。</p><blockquote><p>我定制了【72x99】10丝在售，用于【无损塑封】，既套牌套塑封，牌套的封口对准塑封膜的封口。卡牌可以无损拆出，但是可能有气泡，拿在手里，或轻捏卡牌都能明显感知到有空洞感，牌和牌套之间是空的，而牌套已经黏住塑封膜。</p></blockquote></li><li><p>塑封膜不足8丝留边像照片纸的硬度，10丝更硬一点，8丝折中。</p><ul><li>商家塑封套餐一般用6~8丝。</li></ul></li><li><p>考虑艺都千帆定制（淘宝或阿里巴巴），10包起订，算上邮费，10丝7块多一包，8丝5块多一包。</p></li></ul><blockquote><p>大厂倒角圆润，热熔胶涂布均匀，收缩率低，透明度高。</p></blockquote><ol><li>把卡牌推到封边底，塑封后约4mm留边。</li><li>封短边则上下留边居中比较稳定，左右目视对齐，无法避免偏差。封长边则左右留边比较稳定，我更倾向于封长边。</li><li>塑封膜外径主要影响留边边距，我定制一般四边都留边4mm。</li><li>三国杀官正出血四边都是2~3mm，所以我倾向于留边四边一致。</li><li>通常留边至少3mm，但有一边是目视对齐，稳妥起见预留7mm，避免误差，留8mm。</li></ol><p>三国杀卡牌【62x87】，St尺寸（万智）【63x88】。我会定制三国杀【70x95】，St【71x96】。</p><h3 id="塑封机" tabindex="-1">塑封机 <a class="header-anchor" href="#塑封机" aria-label="Permalink to “塑封机”">​</a></h3><p>几十块塑料壳的塑封机只有两个辊不如铁壳的4辊平整。甲骨文有一款塑封机50多块，A4四胶辊。</p><p>加热方式分为石英管和云母片，石英管是红外灯管。石英管分为内加热和外加热，云母片暂时只有外加热，内加热是把加热管装在胶辊里。外加热是加热管在胶辊旁边加热胶辊。</p><ul><li><p>内加热更均匀，但是加热速度慢，胶辊贵。</p></li><li><p>云母片加热速度快，预热时间短，传热效率高，连续作业效果好，但是成本高。</p><ul><li><p>200￥雷盛LM320-S(T)内加热，塑料齿轮，19mm胶辊。</p></li><li><p>350￥平达330C，云母片，金属齿轮（跟客服要云母片的）。</p></li><li><p>500￥平达330CN是内加热，金属齿轮，25mm胶辊。</p></li><li><p>720￥平达330TD，云母片+可调高速，适合量很大。</p></li></ul></li></ul><p>量小不在乎速度慢优选内加热，量大尽量买云母片+可调高速，石英管外加热温度不均匀，容易出瑕疵。</p><p>塑封机并不是绿灯亮了就可以塑封了，绿灯亮只代表温度传感器检测的点达到设定温度，并不代表整根胶辊的温度都够了。所以使用中可以考虑先调到80~90度，绿灯亮起后预热5分钟左右，再调到需要的温度，再次亮起再酌情开始塑封。温度尽量不要猛猛调高。</p><h3 id="常见塑封异常" tabindex="-1">常见塑封异常 <a class="header-anchor" href="#常见塑封异常" aria-label="Permalink to “常见塑封异常”">​</a></h3><p>雾状白点，不粘，温度不够（设定过低或胶辊温度不均匀或绿灯没亮）。</p><p>泡点（一点一点，点之间有一定间距）温度过高或胶辊需要清洁。</p><p>起皱不平整，温度过高或放置不平整。</p><p>留边不粘或起泡（类似于手机贴膜有气泡），温度不够或胶辊压力不够，有两个有弹簧的螺丝拧一下。</p><h2 id="打印机" tabindex="-1">打印机 <a class="header-anchor" href="#打印机" aria-label="Permalink to “打印机”">​</a></h2><p><strong>喷墨打印前要进行输出锐化</strong>，qimage ultimate软件打印的自带锐化对白字的处理比较好。PS下可以用pixelgenius的PK滤镜，这个输出锐化滤镜是识别高对比反差，白字描黑反而劣化效果。网盘-软件内有。</p><p>家用打印机都是RGB打印机，驱动接收RGB编码，<strong>不需要改成CMYK</strong>。由喷墨程序将RGB编码转换为CMYK喷墨量。要效果好应进行色彩管理，<a href="https://www.bilibili.com/video/BV1gFSCYqE5w" target="_blank" rel="noreferrer">请参考</a>用扫描仪校色打印机。</p><blockquote><p>印刷厂如胶印是CMYK四色油墨分别刷一遍，调整CMYK通道可以优化效果，比如把四色黑改成单色黑可以避免重影。</p></blockquote><ul><li>颜料墨水，原厂墨都可能堵，不会褪色。<strong>至少每周打一次。</strong></li><li>染料墨水，兼容墨都不会堵，但会褪色。</li><li>断线清洗就通的是打印头干了，堵是自己清不通的。</li><li>---</li><li>颜料色稳定，色准高，但由于光线漫射反光会产生烫金效应，反光有明显光泽差异。尤其是C、LC墨水以及CMY混合而成的灰阶。黑位由于反光泛白，感觉不黑。反光还可能泛青铜色，观感怪异。</li><li><strong>颜料反光的怪异感在覆膜之后就没有了</strong>。</li><li>---</li><li>染料需要避光保存。<strong>覆膜或塑封可以明显改善耐候性。</strong></li></ul><h3 id="优选颜料-爱普生p708" tabindex="-1">优选颜料+爱普生P708 <a class="header-anchor" href="#优选颜料-爱普生p708" aria-label="Permalink to “优选颜料+爱普生P708”">​</a></h3><p>6色染料机，无论是L8058还是L8168，加颜料确实都有正常打的，但小毛小病很多，比如有走纸印、棘轮印，润湿好的墨水干得慢留齿轮印（白洞），润湿差的墨水干得快，但是大面积堆墨可能缩孔。</p><p>如果只是照片打印，这些问题可能还能忍忍，但是在DIY桌游上，这些问题在覆膜后都会放大，反光会更显眼。</p><p>最致命的问题，爱普生全面换装压电薄膜打印头，而非以前的压电陶瓷。对墨水的适应性明显更差，我推测可能需要更具有针对性的“驱动波形”，对墨水的物性要求明显比以前高，原装墨水甚至都不一定能保证标准打印质量的稳定性和效果。</p><p>所有这些小毛病，在P708上都是没有的，还有气泵来维持气压平衡，显著改善上颜料的稳定性。就算有些纸张效果不是最理想，也可以修改每Pass干燥时间等墨水干，改善效果，而6色机型不提供类似功能。</p><p><a href="https://chnhi.github.io/lxzdy/ccc/%E8%89%B2%E5%BD%A9%E7%AE%A1%E7%90%86/%E7%88%B1%E6%99%AE%E7%94%9Fp708.html" target="_blank" rel="noreferrer">爱普生P708机型的折腾与维护</a>；<a href="https://chnhi.github.io/lxzdy/ccc/%E8%89%B2%E5%BD%A9%E7%AE%A1%E7%90%86/%E5%85%BC%E5%AE%B9%E5%BD%B1%E5%83%8F%E9%A2%9C%E6%96%99%E5%A2%A8%E6%B0%B4.html" target="_blank" rel="noreferrer">兼容颜料墨水的详细剖析</a>；</p><h3 id="好染料太贵" tabindex="-1"><strong>好染料太贵</strong> <a class="header-anchor" href="#好染料太贵" aria-label="Permalink to “好染料太贵”">​</a></h3><p>兼容染料即使覆膜，数学推测最多撑5年严重褪色，这期间如果要求高，或者敏感其实也能感知到颜色变了。有网友反馈一年不到他就感觉有褪色产生色差了。</p><p><strong>兼容颜料每毫升2毛就不褪色</strong>（以联系我买天威高端788为例）。</p><p>后文折腾墨水有介绍拼配染料，浅洋红，浅青自行用清墨水稀释，黑色用米家原装，洋红、黄用爱普生大幅面染料抽墨，青色用汇美钻石级。</p><p>我DIY的拼配染料，后文【拼配墨水】有介绍。浅洋红，浅青自行用清墨水稀释，黑色用米家原装，洋红、黄用爱普生大幅面染料抽墨，青色用汇美钻石级。搞来搞去，数学推测可能做到15年严重褪色，实际还不一定做得到。每毫升平均折算也要4毛。</p><p>原装014干式彩扩染料墨水单价直接起飞。</p><p>综合来看，我会倾向于：</p><ul><li>爱普生P708+兼容颜料</li><li>爱普生L8168+原装染料。量不大，并且覆膜。</li><li>爱普生L8058+DIY拼配染料。担心颜料堵头，又希望控制成本。</li></ul><p>所以我会推荐indigo彩印，或者联系我喷墨单打印鱼“不晓自在”，6色染料/10色颜料。<a href="./dy.buxiaozizai.com.html">详细了解</a></p><h3 id="染料耐候性" tabindex="-1">染料耐候性 <a class="header-anchor" href="#染料耐候性" aria-label="Permalink to “染料耐候性”">​</a></h3><p>据wilhelm-research实测加数学推测，标准可能是某个墨水的色密度衰减35%，<a href="https://zhuanlan.zhihu.com/p/1911928560123351144" target="_blank" rel="noreferrer">避光无保护的测试进行中</a>：</p><table tabindex="0"><thead><tr><th></th><th>隔绝空气室内光照展示</th><th>室内敞开展示</th><th>无保护避光</th></tr></thead><tbody><tr><td>颜料墨水</td><td>60~200年</td><td>60~200年</td><td></td></tr><tr><td>干扩机染料014(L8168)，D580</td><td>98年</td><td>14年（WIR数据）<br>我测试差很多</td><td></td></tr><tr><td>爱普生6色原装染料（T674）（056?）</td><td>17年</td><td>半年</td><td></td></tr><tr><td>爱普生4色原装染料</td><td>4~5年</td><td>1周</td><td></td></tr><tr><td>兼容耐光染料</td><td></td><td>3~5周（我测试）</td><td></td></tr></tbody></table><ul><li><strong>各家原装墨水除了提到的墨水外都不要考虑</strong>，耐候性都是兼容抗UV染料的水平，对不起价格。</li><li>佳能G580的原装墨水GI-83是chromalife100墨水，彩色耐候性接近干扩机染料，但是黑色耐候性拖了后腿，只是同爱普生6色原厂染料相近。</li><li>A4单面打印，爱普生机型通常共消耗墨水约0.75ml左右，佳能热发泡可能会多消耗一些。</li><li>爱普生大幅面染料抽墨，活的色彩DS6、NDD耐候性同兼容耐光染料差不多。</li></ul><p><strong>染料褪色第一难题，灰平衡。</strong></p><p>染料墨水机型灰阶主要由CMY墨水混合，而CMY墨水褪色速率不一，这往往导致灰平衡破坏的非常快，DS6墨水短短3天，中性灰块的dE00就超过2.5。</p><p>但是灰平衡如果没有参照对比，不一定明显感知。</p><p><strong>染料C墨水褪色速率最快</strong></p><p>以色密度计算，C墨水褪色速率达到M墨水的2.5~4倍。如果无视灰平衡，把C墨水替换成耐候性更好的墨水，可以明显改善整体的耐候性。</p><p><strong>染料黑色墨水褪色发红</strong></p><p>不仅堆黑显眼，而且会参与到彩色增加色密度，跟C墨水一起劣化整体发红的趋势。干式彩扩黑色墨水褪色更偏向饱和度下降显旧，不至于那么显眼。</p><p>如果打算用染料墨水，最好做保护，覆膜、塑封、淋膜，保护后可以不避光。</p><h3 id="打印机只考虑爱普生" tabindex="-1">打印机只考虑爱普生 <a class="header-anchor" href="#打印机只考虑爱普生" aria-label="Permalink to “打印机只考虑爱普生”">​</a></h3><p>参考前文【优选颜料+爱普生P708】，【好染料太贵】。已经详细阐述了我会做的选择，P708+兼容颜料，L8168+原装墨水，L8058+DIY拼配染料。</p><ul><li><strong>打300克铜版纸，厚纸必须后进纸</strong>。如果打印头蹭纸，可以尝试在设置中勾选“厚纸与信封纸”。</li><li>爱普生尽量买L8058、L8168、P708新机，其他机型连续打厚纸可能不够稳定，L426X机壳打不了300克厚纸。</li></ul><p><strong>我只考虑爱普生机型，佳能非常不稳定。</strong></p><p>看看佳能实际用户怎么说：<a href="https://www.bilibili.com/video/BV1T5puz5EbZ" target="_blank" rel="noreferrer">佳能一年要抽吸排气两次</a>；<a href="https://www.zhihu.com/question/590020336/answer/2939677377" target="_blank" rel="noreferrer">被佳能吓尿的网友</a>。佳能只适合商家，天天打，打印头便宜，效果过得去就行。</p><p>爱普生机壳不值钱，打印头值钱，<strong>尽量避免二手爱普生</strong>。爱普生的二手机，大都是商用的，打了几万张，干烂的机器，打印量写在主板上，看似打印量很少的机器，打印头有没有被掉包都不好说。商家收机器，打印量很少的好头，一般600~800可以卖给白墨烫画，UV打印之类的商家。跟着机壳一起卖的往往都是烂泥扶不上墙的打印头，基本上寿命都很短。</p><p>折腾墨水考虑L8058。原装墨水选L8168，耐候性显著强于L8058的原装墨水，色域也明显更广。</p><p><strong>L8168机型的走纸印在中间，避不开，L8058的走纸印在两边约1cm左右，可以避开</strong>。新出货的L8168有可能也改了，他们机壳很多设计都是通用的。</p><p>爱普生P708、佳能PRO510定位影像，一般没有走纸印，棘轮印也不易感知。</p><p><strong>佳能4~6色机型的走纸印情况要比爱普生好</strong>，棘轮印半斤八两。不过覆PET哑膜后浅色基本感知不到，深色可能感知到。</p><p><strong>便宜机器只有佳能，看似买机壳便宜，但是打印头相当于耗材，成本一下子就上去了</strong>。</p><p>佳能打印头寿命实在太短，只有用原装墨水考虑全新G580，1000出头就导入了灰色墨水。</p><p>E478机壳前身mg3080打不了厚纸。便宜机身考虑TS5380，跟这个机壳共用进纸组件的g5080等墨仓型号，有后进纸的，能打厚纸。高质量彩打既选光泽照片纸，黑墨不喷墨，是CMY混合的黑色，相对不黑，而且因为CMY褪色速度不一样，打出来的黑色褪色更快更显眼。</p><p>二手TS5380，喷嘴折腾坏了买个新墨盒打洞就行，墨盒容量实在太小，最好配合三仓连供，按说明处理气压平衡，不然稳定性不太理想。</p><p>TS9020、TS8020、TS5080等几个二手机比较便宜，但能不能买到靠谱的打印头非常看运气，往往可能买来是好的，但连续打印会掉链子。</p><p><img src="https://s2.loli.net/2025/02/12/2NWyDfeOxgutMdq.jpg" alt="1.jpg"></p><p><img src="https://s2.loli.net/2025/02/12/XL5EamtwiMfs9PC.jpg" alt=".jpg"></p><h3 id="折腾墨水" tabindex="-1">折腾墨水 <a class="header-anchor" href="#折腾墨水" aria-label="Permalink to “折腾墨水”">​</a></h3><p><a href="https://chnhi.github.io/lxzdy/ccc/%E8%89%B2%E5%BD%A9%E7%AE%A1%E7%90%86/%E7%88%B1%E6%99%AE%E7%94%9Fp708.html" target="_blank" rel="noreferrer">爱普生P708机型的折腾与维护</a>；<a href="https://chnhi.github.io/lxzdy/ccc/%E8%89%B2%E5%BD%A9%E7%AE%A1%E7%90%86/%E5%85%BC%E5%AE%B9%E5%BD%B1%E5%83%8F%E9%A2%9C%E6%96%99%E5%A2%A8%E6%B0%B4.html" target="_blank" rel="noreferrer">兼容颜料墨水的详细剖析</a>；</p><p>本文不赘述兼容颜料，👆链接跳转参考。</p><ul><li>不打算用原装墨水可以买拆墨空机。</li></ul><p><strong>换任何墨水都必须校色。</strong><a href="https://zhuanlan.zhihu.com/p/441885301" target="_blank" rel="noreferrer">扫描仪校色打印机</a>；<a href="https://zhuanlan.zhihu.com/p/622264483" target="_blank" rel="noreferrer">校色仪校色打印机</a>；</p><p><strong>如果墨水更匹配喷墨程序，往往灰阶相对更中性，校色事半功倍。</strong>另色鬼056-RC专用龙纹，是我见过相对最匹配L8058机型喷墨程序的兼容墨水。</p><p>L8058的原装056墨水，耐候性相对014墨水有较大差距，但是价格却不便宜，我觉得有点小坑。</p><p><strong>买任何所谓原装墨水，拆机墨水，</strong>务必在爱普生或佳能官网能查到的店铺购买。真正卖拆机墨水的很不好搜到，而且倾向于整套一起卖。一搜就搜到，出货量很大，贼便宜的拆机墨水99%是假货。</p><p>据网友反馈，其于<strong>强东自营</strong>买的L8168，随机墨水竟然有严重的耐候性问题，密封保存竟然一天一变。换真墨水之后，密封保存一个月都没变化（通过重新打印对比）。市场上疑似存在严重的真假墨水混卖现象，买原装墨水请务必自测耐候性。<em>不清楚是退货被掉包了还是怎么回事</em>。</p><ul><li>不在乎成本用干式彩扩机墨水，耐候性好很多。</li><li>兼容“耐光抗UV”染料避光或保护，见光无保护2~4周褪色。</li><li>C墨水褪色速率最快，用好的可以改善耐候性。</li></ul><p>保护既覆膜、塑封、淋膜，压在玻璃、亚克力等材料下也可以，保护后可以不避光，可能是光子激发反应时，还需要氧气参与反应。</p><p><strong>干式彩扩机墨水：</strong>L8168(014)，D580（墨瓶）；D700，D880，D1080（墨盒）。富士墨盒。浅色墨水（GY，LC，LM）可以<a href="https://zhuanlan.zhihu.com/p/27494317739" target="_blank" rel="noreferrer">自行稀释</a>。</p><p><strong>兼容染料色域不差，但是耐候性太差。必须买抗UV耐光染料，普通染料一天就变色。</strong></p><p>兼容“耐光抗UV”染料据我<a href="https://zhuanlan.zhihu.com/p/1911928560123351144" target="_blank" rel="noreferrer">测试</a>，所有品牌都没有质变，哪个便宜买哪个。哪个便宜买哪个。另色鬼056-RC专用龙纹，是我见过相对最匹配L8058机型喷墨程序的兼容墨水。<strong>格之格贴牌传美讯代工；</strong>天威；商用成本优先墨库百度西。</p><p><strong>只换C墨水改善耐候性</strong>优选原装014C墨水，056、汇美钻石级便宜。C换了好的，我感觉LC可能也要换，<a href="https://zhuanlan.zhihu.com/p/27494317739" target="_blank" rel="noreferrer">或自行稀释好的。</a></p><p><strong>黑色墨水</strong>矬子里拔将军，另色鬼影像染料、鸿盛EverNew、天威R330影像级染料。另色鬼，鸿盛褪色发黄显旧，天威这款褪色发红不过色密度衰减慢点。</p><h3 id="拼配墨水" tabindex="-1">拼配墨水 <a class="header-anchor" href="#拼配墨水" aria-label="Permalink to “拼配墨水”">​</a></h3><p>拼配墨水是耐候性和成本的折中，折合约每毫升4毛的成本，耐候性约是兼容染料的3倍，原装干扩染料的三分之一，而原装干扩染料成本约每毫升1块2左右。</p><p>其中稀释用的清墨水、大幅面染料活的色彩DS6抽墨M和Y可以联系我买。</p><p>爱普生专利，SDS披露复刻清墨水配方：三甘醇15%，三乙二醇12%，三乙二醇单丁醚8%，三乙醇胺0.25%，2-吡咯烷酮2.5%，BIT防腐剂0.02%，Surfynol 465-0.8%，Surfynol 104E-0.1%。</p><p>C-汇美004钻石级墨水（24￥/70ml）</p><p>Lc-20%重量比例稀释</p><p>M-活的色彩DS6抽墨</p><p>Lm-25%重量比例稀释</p><p>Y-活的色彩DS6抽墨</p><p>K-米家连供喷墨原装墨水抽墨（39￥/58ml）</p><p>做出来的ICC显示，在亮部线性不错，也就是稀释的浅色墨水比较匹配，就是大幅面Y墨水相对原装056的Y墨水太深，可能要稍微稀释一下。暗部的话线性不是最匹配，可能是深色墨水太浓，要稍微稀释一点，不过也不一定。</p><p>原装056可能是红光黄色染料，常见的Y染料墨水可能是绿光黄色染料，本身显色性上就有差异。</p><p><a href="https://pan.baidu.com/s/1zSW2UQ2NfF16cG7zuKrDvg?pwd=bxzz" target="_blank" rel="noreferrer">我分享的校色ICC</a>。</p><h3 id="纸" tabindex="-1">纸 <a class="header-anchor" href="#纸" aria-label="Permalink to “纸”">​</a></h3><ul><li><strong>印刷厂</strong>俗称<strong>铜版纸</strong>的纸张，准确来说是 印刷涂布纸coated art paper。</li></ul><p>没有喷墨涂层，喷墨打印机要用铜版纸颜料墨水（快干颜料墨水），最好改装加热装置。墨水加大粘结剂（成膜树脂、乳化蜡）用量，添加挥发性溶剂如异丙醇加快速干。</p><p>低温下粘度会变高，打印容易斜喷或断线。只适合商用天天打，不然堵头风险较大。正如前文【优选颜料】所介绍，我会认为爱普生4~6机型用这样的墨水恐怕稳定性不会是最理想。</p><ul><li>喷墨用的” <strong>高光铜版纸</strong> “，准确来说是“喷墨铜版纸”inkjet coated paper。</li></ul><p>有喷墨涂层，可以吸收更多墨水增加色密度，色彩表现力相当不错。但是：</p><ol><li>涂层也计入克重，相同克重下更薄更软。</li><li><strong>反光能感知走纸印和棘轮印，两张卡摩擦有白痕，必须要保护。</strong></li><li>覆PET哑膜可以改善走纸印和棘轮印。</li><li>最好用染料墨水。颜料墨水不覆膜反光观感怪异。</li><li>颜料需要爱普生P708机型增加每PASS等待时间，延长干燥时间，4~6色机型打印过程中有概率蹭掉图案，产生一条白痕（L8168内置的长干燥时间不够）。</li></ol><ul><li>”<strong>白卡纸</strong>“。有350g，400g。</li></ul><p>白卡纸克重就是纯纸，最硬挺。但是靠纸基吸墨，色密度<strong>严重受限</strong>，影响表现力，由于墨水被纸张吸收，会泛纸张本色，显得色密度不够。颜料要原装粗面黑才比较黑，但是不耐刮擦，手一摸就变黑。</p><ul><li>哑光喷墨铜版纸，matte inkjet coated paper。</li></ul><p>所谓“哑光铜版纸”有两类，一类实质就是白卡纸。另一类有涂层。有涂层的我买到过两种：</p><p>1、骏马纸业代工，很多小牌子的所谓哑光铜版纸就是贴牌。这个纸我认为可以称为“丝光彩喷纸”。说是哑光，实际上还是有轻微的反光。相对高光铜版纸，走纸印和棘轮印有很大的改善，基本要反光细品才能感知到有走纸印。但是表现力相对高光铜版纸要稍差些。</p><p><strong>这个纸经常本身涂层上就有斑驳的痕迹，覆膜后会很明显。</strong></p><p>必须覆膜，不覆膜切割后，切口处涂层会有皲裂。覆膜后染料颜料都可以用。</p><p>2、我称为”哑光彩喷纸“，有涂层但是不会反光，表现力相对“丝光彩喷纸”要差。我买到过力武的“哑光铜版纸”是这类。</p><p>搭配颜料墨水，黑色墨水堆积的地方会有反光，其他地方又没有反光，反光就会有一点斑驳。这款纸如果天气潮湿，4~6色机型颜料墨水干的慢，会有明显走纸印。</p><ul><li>增强粗面艺术纸</li></ul><p>走纸印和棘轮印相对哑光铜版纸还要进一步改善，不怎么能感知到，但是由于是涂层和纸基一起吸墨，所以精度锐度相对会差一些，成本还高。颜料要原装粗面黑才比较黑，但是不耐刮擦，手一摸就变黑，不然会泛纸白。</p><p>搭配颜料墨水没有烫金效应，观感比较“自然”温暖，但是要写实的作品才能体现，自印卡基本没有。</p><ul><li><strong>RC细绒相纸</strong>搭配颜料墨水有非常强的表现力，但又软又薄，可以考虑白条卡或塑封。</li></ul><p>RC相纸色域最广，广很多。不易感知走纸印，细品可能感知棘轮印。</p><ul><li>莱妮纹 珠光纸，布纹效果。</li><li>diy局部镭射闪卡常用的镭射透明不干胶，透明pet等可以打颜料墨水。</li></ul><p><a href="https://chnhi.github.io/lxzdy/ccc/%E8%89%B2%E5%BD%A9%E7%AE%A1%E7%90%86/%E6%89%93%E5%8D%B0%E6%9C%BA.html#%E5%96%B7%E5%A2%A8%E4%B8%8E%E7%89%B9%E6%AE%8A%E7%BA%B8" target="_blank" rel="noreferrer">简单介绍工业用墨水请参考。</a></p><blockquote><p>工业墨水：弱溶剂墨水，乳胶墨水，涂料墨水（DTF烫画墨水），UV墨水等，腐蚀打印介质或通过不同原理固化成膜，极易堵头，还具有强腐蚀性，<strong>非工业打印头寿命按天计算。</strong></p></blockquote><h2 id="diy-pvc卡" tabindex="-1">DIY-PVC卡 <a class="header-anchor" href="#diy-pvc卡" aria-label="Permalink to “DIY-PVC卡”">​</a></h2><p>DIY可行的PVC卡有两种，一种是PVC免层压，另一种是喷墨PVC白卡。</p><p><strong>PVC免层压</strong>是PVC卡上涂有热熔胶，打印在PET透明膜上（有喷墨涂层）然后过塑封机，把PET透明膜和PVC卡胶合，然后用重型冲卡器冲卡。热熔胶寿命不长会脱胶，甚至刚做完就起泡。</p><p>L8058机型有PVC证卡托架，可以打印在PVC白卡上，必须是<strong>喷墨PVC白卡</strong>，涂布了喷墨涂层。缺点是只有86x54尺寸。最好用颜料墨水。</p><p>88x63尺寸我估计应该是可以打的，只不过喷墨白卡和托架都要定制，不知道在哪定制托架。</p><p>L8168机型有一个后部进纸槽，把屁股掀开可以平行进纸。网上搜 L8168 打印证卡看看视频，自己3d打印一个类似的托盘，自己在InDesign软件微调出适配的模板文件。</p><h2 id="测试不适合diy的" tabindex="-1">测试不适合diy的 <a class="header-anchor" href="#测试不适合diy的" aria-label="Permalink to “测试不适合diy的”">​</a></h2><h3 id="切卡-1" tabindex="-1">切卡 <a class="header-anchor" href="#切卡-1" aria-label="Permalink to “切卡”">​</a></h3><p>  手动模切机配刀模，挨得太近压力不够会撕扯打印面，而且免不了会有一点位移刮伤打印面，感觉电动模切机也够呛。</p><p>  刻字机，要打标记点给机器巡边，A4只能切6张卡，而且机器不能校正角度偏斜，要自己对齐摆放，会有刀口毛刺，而且切割要有垫板保护刀头，垫板有粘性，所以必须要给纸覆膜，或本身就是不干胶有背纸，不然打印面会粘在垫板上。</p><h3 id="保护" tabindex="-1">保护 <a class="header-anchor" href="#保护" aria-label="Permalink to “保护”">​</a></h3><ul><li>双面RC细绒相纸+水性光油。</li></ul><p>  水光油用丝印尖口刮刀在RC相纸的打印面刷一遍，不需要丝印网板，就能实现不错的光泽度和顺滑的手感。裸卡重叠在一起相互摩擦，分离非常顺滑，但是相对原卡明显薄软很多。RC绒面观感更有质感，但与原卡明显不同。</p><p><strong>但手动涂布免不了出现瑕疵。</strong></p><blockquote><p>RC相纸表面有一层淋膜，防水，水光油不会马上成膜，而且是孔隙结构，用水光油中的树脂颗粒填充孔隙后，光泽度好，手感顺滑。铜版纸是一层蜡，手动涂布不够均匀，成膜效果不佳。</p></blockquote><ul><li>uv光油</li></ul><p>  uv打印机打光油，手感不润。手动涂布光油墨水会有油性物质渗进纸张，不清楚是溶剂还是稀释剂之类的成分。</p><p>  UVC光油，丝印尖口刮刀不需要丝网，可以薄薄的挂一层，要用高压汞灯，对皮肤，人眼都有伤害，有刺鼻的刺激性气味。LED-UV灯，365或395nm波长的不行。</p><p>  原卡一般是过水光油，硬度高，手感顺滑，还会压光（磨光）磨薄涂层。UV光油硬度差很多，顺滑程度明显不如。</p><blockquote><p>橡胶滚筒瑕疵多一些，较厚，明显感知。</p></blockquote><blockquote><p>丝印网板缺点是没有喷枪清洗不干净，效果比滚筒好，但是从网板拿下来的时候会有痕迹。</p></blockquote><ul><li>亮色墨水</li></ul><p>  爱普生P408和佳能pro-300有亮光色墨水通道，但都只是薄薄的覆一层，不能在哑面纸上实现光泽，但是可以实现卡变得很顺滑。</p><ul><li>水性光油</li></ul><p>  工业用的水性光油，线棒涂布不能流平有纹路，丝网会黏住，塑封机会留下胶辊上的纹理，还会黏到灰尘。喷漆枪要喷的厚一点，但还是免不了会有麻子，往往喷涂量过大，导致纸张吸水，干燥后纸张会翘曲变形。橡胶滚筒不能均匀涂抹。</p><blockquote><p>铜版纸只有表面的蜡有一定防水性能，纸芯不防水。</p></blockquote><ul><li>油墨光油</li></ul><p>  油墨光油，黄黄的，不是很透。橡胶滚筒效果凑合，太厚，干的太慢，要几十个小时，免不了会沾到灰尘。油墨要用天拿水清洗，用水冲没用。油墨本身味道较淡，但是天拿水味道相当大，相当上头。</p>`,217)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};